import { defineConfig } from 'vitest/config';

// The server's tests import the extension's src/ (the contract, src/world). Pin the transform to this tsconfig so it
// doesn't walk up to the root one, which extends .wxt/tsconfig.json: generated by the root install (wxt prepare),
// absent where only the server is installed (CI's server job, a fresh `cd server && npm ci`).
export default defineConfig({ tsconfig: './tsconfig.json' });
